import { test, expect } from '@playwright/test';

test('each added todo item has a unique data-testid attribute', async ({ page }) => {
  await page.goto('/');
  await page.getByTestId('nav-todo').click();
  await page.getByTestId('todo-input').fill('Item 1');
  await page.getByTestId('add-todo-button').click();
  await page.getByTestId('todo-input').fill('Item 2');
  await page.getByTestId('add-todo-button').click();
  const todoItems = page.locator('[data-testid^="todo-item-"]');
  const testIds = await todoItems.all().then(items => items.map(item => item.getAttribute('data-testid')));
  expect(new Set(testIds)).toEqual(new Set(['todo-item-0', 'todo-item-1']));
});

